from .base import Xml, ScfcFixerException


class Scfc(Xml):

    CMDATA_PATH = '{*}cmData'
    ALL_MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject'
    MANAGED_OBJECT_PATH = CMDATA_PATH + '/{*}managedObject[@distName="{dist_name}"]'
    MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject[@class="{managed_object_class}"]'

    def find_managed_object(self, dist_name):
        """Returns an object representing given managed object"""
        managed_object_node = self._find_managed_object_node(dist_name)
        return ManagedObject(managed_object_node)

    def _find_managed_object_node(self, dist_name):
        return self._find_node_or_raise(self.MANAGED_OBJECT_PATH, dist_name=dist_name, exception_class=NoSuchManagedObject)

    def find_managed_objects(self, managed_object_class):
        """Returns a list of objects representing all managed objects of given class"""
        managed_object_nodes = self._find_all_nodes(self.MANAGED_OBJECTS_PATH, managed_object_class=managed_object_class)
        return [ManagedObject(node) for node in managed_object_nodes]

    def find_all_managed_objects(self):
        """Returns a list of objects representing all managed objects"""
        managed_object_nodes = self._find_all_nodes(self.ALL_MANAGED_OBJECTS_PATH)
        return [ManagedObject(node) for node in managed_object_nodes]

    def add_managed_object(self, dist_name, version=None):
        """Adds an empty managed object"""
        version = version or self._find_version()
        managed_object_class = self._get_managed_object_class(dist_name)
        cmdata_node = self._find_cmdata_node()
        managed_object_node = self._add_element(cmdata_node, 'managedObject')
        managed_object_node.set('class', managed_object_class)
        managed_object_node.set('distName', dist_name)
        managed_object_node.set('operation', 'create')
        managed_object_node.set('version', version)
        self._fix_inner_indentation(managed_object_node)
        return ManagedObject(managed_object_node)

    def _find_cmdata_node(self):
        return self._find_node_or_raise(self.CMDATA_PATH, exception_class=ScfcFixerException)

    def _find_version(self):
        managed_objects = self.find_all_managed_objects()
        if len(managed_objects) is 0:
            raise ScfcFixerException('Cannot find the version of SCFC because there are no managed objects')
        return managed_objects[0].version

    def remove_managed_object(self, dist_name):
        """Removes the managed object with given dist name"""
        node = self._find_managed_object_node(dist_name)
        self._remove_element(node)


class ManagedObject(Xml):

    LIST_PATH = '{*}list[@name="{list_name}"]'
    LIST_ITEMS_PATH = LIST_PATH + '/{*}item'
    PARAM_PATH = '{*}p[@name="{param_name}"]'
    LIST_WRAPPER_PATH = '{*}list[@name="{param_name}"]'
    PARAM_MULTIPLE_PATH = LIST_WRAPPER_PATH + '/{*}p'

    @property
    def version(self):
        """Version (eNB SW branch) of this managed object"""
        return self.xml.get('version')

    @property
    def dist_name(self):
        """Dist name of this managed object"""
        return self.xml.get('distName')

    @property
    def id(self):
        """Id of this managed object (last part of dist name, e.g. 2 for DIST-1/NAME-2)"""
        return int(self.dist_name.rsplit('-', 1)[1])

    @property
    def klass(self):
        """Class of this managed object"""
        return self.xml.get('class')

    def find_list_param(self, list_name):
        """Returns a list of objects representing all lists with given name"""
        list_node = self._find_node_or_raise(self.LIST_PATH, list_name=list_name, exception_class=NoSuchListParameter)
        return ListParam(list_node)

    def find_param(self, param_name, param_value=None):
        """Returns an object representing the first matching parameter with given name and value in this managed object.
        Parameters inside lists are skipped."""
        node = self._find_param_node(param_name, param_value)
        return Param(node)

    def _find_param_node(self, param_name, param_value):
        if param_value is None:
            return self._find_param_node_by_name(param_name)
        else:
            return self._find_param_node_by_name_and_value(param_name, param_value)

    def find_params(self, param_name):
        """Returns a list of objects representing all parameters with given name"""
        return [Param(node) for node in self._find_all_param_nodes_by_name(param_name)]

    def _find_param_node_by_name(self, param_name):
        param_node = self._find_node(self.PARAM_PATH, param_name=param_name)
        if param_node is None:
            param_node = self._find_node(self.PARAM_MULTIPLE_PATH, param_name=param_name)
        if param_node is None:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH + ' or ' + self.PARAM_MULTIPLE_PATH, param_name=param_name)
        return param_node

    def _find_all_param_nodes_by_name(self, param_name):
        return self._find_all_nodes(self.PARAM_PATH, param_name=param_name) \
            + self._find_all_nodes(self.PARAM_MULTIPLE_PATH, param_name=param_name)

    def _find_param_node_by_name_and_value(self, param_name, param_value):
        param_nodes = self._find_all_param_nodes_by_name(param_name)
        nodes_with_value = [node for node in param_nodes if node.text == param_value]
        if len(nodes_with_value) == 0:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH + ' or ' +
                                          self.PARAM_MULTIPLE_PATH, param_name=param_name, param_value=param_value)
        else:
            return nodes_with_value[0]

    def add_param(self, param_name, param_value, multiple=False):
        """Adds a parameter to this managed object"""
        if multiple:
            return self._add_duplictated_param(param_name, param_value)
        else:
            return self._add_single_param(param_name, param_value)

    def add_list_param(self, list_name):
        """Adds an empty list to this managed object"""
        list_node = self._add_element(self.xml, 'list')
        list_node.set('name', list_name)
        return ListParam(list_node)

    def _add_single_param(self, param_name, param_value):
        param_node = self._add_element(self.xml, 'p')
        param_node.set('name', param_name)
        param_node.text = param_value
        return Param(param_node)

    def _add_duplictated_param(self, param_name, param_value):
        self._ensure_list_wrapper_for_duplicated_param_exists(param_name)
        list_wrapper_node = self._find_list_wrapper_for_duplicated_param(param_name)
        param_element = self._add_element(list_wrapper_node, 'p')
        param_element.text = param_value
        return Param(param_element)

    def _ensure_list_wrapper_for_duplicated_param_exists(self, param_name):
        if self._find_list_wrapper_for_duplicated_param(param_name) is None:
            self._add_list_wrapper_for_duplicated_param(param_name)

    def _find_list_wrapper_for_duplicated_param(self, param_name):
        return self._find_node(self.LIST_WRAPPER_PATH, param_name=param_name)

    def _add_list_wrapper_for_duplicated_param(self, param_name):
        list_element = self._add_element(self.xml, 'list')
        list_element.set('name', param_name)
        self._fix_inner_indentation(list_element)

    def remove_param(self, param_name, param_value=None):
        """Removes the first found parameter with given name and value (not inside a list)"""
        node_to_remove = self._find_param_node(param_name, param_value)
        self._remove_element(node_to_remove)

    def remove_params(self, param_name):
        """Removes all parameters with given name (not inside a list)"""
        nodes_to_remove = self._find_all_param_nodes_by_name(param_name)
        for node_to_remove in nodes_to_remove:
            self._remove_element(node_to_remove)


class ListParam(Xml):

    ITEMS_PATH = '{*}item'
    PARAM_IN_ITEM_PATH = '{*}p[@name="{param_name}"]'
    PARAM_PATH = ITEMS_PATH + '/' + PARAM_IN_ITEM_PATH

    def find_param(self, param_name, param_value=None):
        """Returns the first parameter with given name and value"""
        node = self._find_param_node(param_name, param_value)
        return Param(node)

    def find_params(self, param_name):
        """Returns all parameters with given name"""
        return [Param(node) for node in self._find_all_param_nodes_by_name(param_name)]

    def _find_param_node(self, param_name, param_value):
        if param_value is None:
            node = self._find_param_node_by_name(param_name)
        else:
            node = self._find_param_node_by_name_and_value(param_name, param_value)
        return node

    def _find_param_node_by_name(self, param_name):
        return self._find_node_or_raise(self.PARAM_PATH, exception_class=NoSuchParameter, param_name=param_name)

    def _find_all_param_nodes_by_name(self, param_name):
        return self._find_all_nodes(self.PARAM_PATH, param_name=param_name)

    def _find_param_node_by_name_and_value(self, param_name, param_value):
        param_nodes = self._find_all_param_nodes_by_name(param_name)
        nodes_with_value = [node for node in param_nodes if node.text == param_value]
        if len(nodes_with_value) == 0:
            self._raise_on_node_not_found(NoSuchParameter, self.xml, self.PARAM_PATH, param_name=param_name, param_value=param_value)
        else:
            return nodes_with_value[0]

    def add_param(self, param_name, param_value):
        """Adds a parameter to this list. If a parameter with the same name exists, a duplicated parameter is added (to another <item>)"""
        self._ensure_has_items_node()
        self._ensure_has_items_node_without_param(param_name)
        items_node = self._find_items_node_without_param(param_name)
        param_element = self._add_element(items_node, 'p')
        param_element.set('name', param_name)
        param_element.text = str(param_value)
        return Param(param_element)

    def _find_items_node(self):
        return self._find_node(self.ITEMS_PATH)

    def _find_all_items_nodes(self):
        return self._find_all_nodes(self.ITEMS_PATH)

    def _find_items_node_without_param(self, param_name):
        items_nodes = self._find_all_items_nodes()
        param_in_item_path = self._parametrize_path(self.PARAM_IN_ITEM_PATH, param_name=param_name)
        nodes_without_param = [node for node in items_nodes if node.find(param_in_item_path) is None]
        return nodes_without_param[0] if len(nodes_without_param) > 0 else None

    def _ensure_has_items_node(self):
        if not self._has_items_node():
            self._fix_inner_indentation(self.xml)
            self._add_items_node()

    def _ensure_has_items_node_without_param(self, param_name):
        if self._find_items_node_without_param(param_name) is None:
            self._add_items_node()

    def _add_items_node(self):
        items_node = self._add_element(self.xml, 'item')
        self._fix_inner_indentation(items_node)

    def _has_items_node(self):
        return self._find_items_node() is not None

    def remove_param(self, param_name, param_value=None):
        """Removes the firs found parameter with given name and value"""
        node_to_remove = self._find_param_node(param_name, param_value)
        parent_items_node = node_to_remove.getparent()
        self._remove_element(node_to_remove)
        if self._is_empty(parent_items_node):
            self._remove_element(parent_items_node)
        if self._is_empty(self.xml):
            self.xml.text = None


class Param(Xml):

    @property
    def value(self):
        """Value of this parameter"""
        return self.xml.text

    @value.setter
    def value(self, new_value):
        """Value of this parameter"""
        self.xml.text = str(new_value)


class NoSuchManagedObject(ScfcFixerException):
    """Raised when needed managed object does not exist in SCFC"""


class NoSuchListParameter(ScfcFixerException):
    """Raised when needed list parameter does not exist in SCFC"""


class NoSuchParameter(ScfcFixerException):
    """Raised when needed parameter does not exist in SCFC"""
